INSERT INTO articles (title, summary, content, category, author, status, publishedAt) VALUES 
('集团完成 C 轮融资，加速边缘计算全球布局', '近日，集团宣布完成 C 轮融资，由知名投资机构领投，融资金额达数亿元。本轮融资将用于加速边缘计算节点的全球部署，加大研发投入，拓展海外市场。', '<p>详细内容...</p>', '公司新闻', '集团办公室', 'published', '2024-01-15'),
('果壳网络边缘计算节点突破 2800 个，覆盖全球主要地区', '福州果壳网络科技有限公司宣布，其 CDN 边缘计算节点数量已突破 2800 个，覆盖全球 200+ 国家和地区，日请求处理量超过 1000 亿次，服务稳定性达到 99.99%。', '<p>详细内容...</p>', '公司业务', '果壳网络', 'published', '2024-01-10'),
('楷熵信息荣获"年度最佳支付解决方案提供商"奖项', '在第三届中国支付产业高峰论坛上，福州楷熵信息技术有限公司凭借创新的支付技术和优质的服务，荣获"年度最佳支付解决方案提供商"奖项。', '<p>详细内容...</p>', '公司荣誉', '楷熵信息', 'published', '2024-01-05'),
('远方在线电商业务年 GMV 突破 50 亿元，同比增长 150%', '福州远方在线科技有限公司 2023 年业绩亮眼，全年 GMV 突破 50 亿元，同比增长 150%。其中，私域电商业务增长迅猛，成为新的增长引擎。', '<p>详细内容...</p>', '公司业务', '远方在线', 'published', '2024-01-03'),
('集团通过 ISO27001 信息安全管理体系认证', '集团正式通过 ISO27001 信息安全管理体系认证，标志着集团在信息安全管理方面达到国际标准，为客户提供更安全可靠的服务保障。', '<p>详细内容...</p>', '公司荣誉', '集团办公室', 'published', '2023-12-28'),
('集团与多家银行达成战略合作，提升支付服务能力', '楷熵信息与工商银行、建设银行、招商银行等多家主流银行签署战略合作协议，将在支付清算、跨境支付、供应链金融等领域展开深度合作。', '<p>详细内容...</p>', '公司合作', '楷熵信息', 'published', '2023-12-20'),
('2024 年中国 CDN 市场规模将突破 500 亿元', '据权威机构预测，2024 年中国 CDN 市场规模将突破 500 亿元，同比增长 25%。边缘计算、5G 应用、超高清视频等新兴需求成为主要增长动力。', '<p>详细内容...</p>', '行业资讯', 'IDC 研究', 'published', '2024-01-12'),
('央行发布支付行业新规，促进行业健康发展', '中国人民银行发布《非银行支付机构监督管理条例》，进一步完善支付行业监管框架，促进行业规范健康发展，保护消费者合法权益。', '<p>详细内容...</p>', '行业政策', '中国人民银行', 'published', '2024-01-08'),
('直播电商市场规模持续扩大，2024 年有望突破 3 万亿', '2023 年中国直播电商市场规模达 2.5 万亿元，同比增长 40%。预计 2024 年将继续保持高速增长，市场规模有望突破 3 万亿元。', '<p>详细内容...</p>', '行业趋势', '艾瑞咨询', 'published', '2024-01-06'),
('跨境电商迎来政策利好，多部门出台支持措施', '商务部、海关总署等多部门联合出台支持跨境电商发展的政策措施，包括优化通关流程、完善税收政策、加强海外仓建设等。', '<p>详细内容...</p>', '行业政策', '商务部', 'published', '2024-01-02'),
('AI 技术在支付风控领域的应用日益广泛', '随着人工智能技术的发展，越来越多的支付机构将 AI 应用于交易风控、反欺诈、信用评估等领域，显著提升风控效率和准确性。', '<p>详细内容...</p>', '行业技术', '支付产业观察', 'published', '2023-12-25'),
('私域流量运营成为电商新趋势', '在公域流量成本持续上升的背景下，私域流量运营成为电商企业的新选择。小程序、社群、直播等私域运营方式受到品牌商青睐。', '<p>详细内容...</p>', '行业趋势', '电商研究中心', 'published', '2023-12-18');
